"""Pure deferred public-output binding. No cloud lookup or approval inference."""
from dataclasses import dataclass
import hashlib
import json
from pathlib import Path
import re
if __package__:
    from .workflow_profile import ApplicationProfile,IDENTITY_KEYS
    from .workflow_payload import encoded
else:
    from workflow_profile import ApplicationProfile,IDENTITY_KEYS
    from workflow_payload import encoded

ENVIRONMENTS={'staging','production','qualification'}
PROVIDERS={'aws','azure','gcp','ibm','tools'}


def reference(value):
    if type(value)is not dict or set(value)!={'nativeOutput'}:raise ValueError('Use an explicit public native-output reference')
    ref=value['nativeOutput']
    if type(ref)is not dict or set(ref)!={'componentId','provider','environment','name'}:raise ValueError('Use an exact native-output owner')
    if type(ref['componentId'])is not str or not 1<=len(ref['componentId'].encode())<=512 or any(ord(c)<32 for c in ref['componentId']):raise ValueError('Use the complete output component identity')
    if type(ref['provider'])is not str or ref['provider']not in PROVIDERS or type(ref['environment'])is not str or ref['environment']not in ENVIRONMENTS:raise ValueError('Use the exact output provider/environment')
    if type(ref['name'])is not str or not re.fullmatch(r'[A-Za-z][A-Za-z0-9_]{0,79}',ref['name'])or re.search(r'secret|password|credential|private_?key',ref['name'],re.I):raise ValueError('Only reviewed public output names may bind')
    return ref


@dataclass(frozen=True,init=False)
class ApplicationTemplate:
    _encoded:bytes

    def __init__(self,value):
        raw=encoded(value);data=json.loads(raw)
        if type(data)is not dict or data.get('format')!='approval-application-template-v1':raise ValueError('Use a versioned application template')
        trial=json.loads(raw);trial['format']='approval-application-v1';refs=[]
        if type(trial.get('publicOrigin'))is dict:
            refs.append(('publicOrigin',reference(trial['publicOrigin'])));trial['publicOrigin']='https://unresolved.invalid'
        identity=trial.get('identitySettings')
        if type(identity)is dict:
            for key,val in identity.items():
                if type(val)is dict:refs.append(('identitySettings/'+key,reference(val)));identity[key]='UNRESOLVED_NATIVE_OUTPUT'
        dest=trial.get('destinationContract')
        if type(dest)is dict:
            for key in ['endpointSha256','scope']:
                if type(dest.get(key))is dict:
                    refs.append(('destinationContract/'+key,reference(dest[key])));dest[key]='0'*64 if key=='endpointSha256'else'unresolved'
        ApplicationProfile(trial)
        if not refs:raise ValueError('A deferred template must retain at least one output reference')
        for path,ref in refs:
            if ref['environment']!=data['environment']:raise ValueError('Output environment differs from the application template')
            if path.startswith('identitySettings/')and ref['provider']!=data['provider']:raise ValueError('Native identity output provider differs from the selected adapter')
        object.__setattr__(self,'_encoded',raw)

    @property
    def data(self):return json.loads(self._encoded)
    @property
    def sha256(self):return hashlib.sha256(self._encoded).hexdigest()
    @property
    def references(self):
        data=self.data;result=[]
        for key in ['publicOrigin']:
            if type(data[key])is dict:result.append({'path':key,**reference(data[key])})
        for section in ['identitySettings','destinationContract']:
            for key,value in data[section].items():
                if type(value)is dict:result.append({'path':section+'/'+key,**reference(value)})
        return result


def application_declaration(value):
    return ApplicationTemplate(value)if type(value)is dict and value.get('format')=='approval-application-template-v1'else ApplicationProfile(value)


def resolve_template(template,ledger):
    if type(template)is not ApplicationTemplate:raise ValueError('Use an immutable owned template')
    raw=encoded(ledger);ledger=json.loads(raw)
    if type(ledger)is not dict or set(ledger)!={'version','outputs'}or type(ledger['version'])is not int or ledger['version']!=1 or type(ledger['outputs'])is not list or not 1<=len(ledger['outputs'])<=128:raise ValueError('Use a bounded public-output ledger')
    by_key={};snapshots={}
    for item in ledger['outputs']:
        if type(item)is not dict or set(item)!={'componentId','provider','environment','name','value','sensitive','sourceSha256'}:raise ValueError('Use exact public output records')
        reference({'nativeOutput':{key:item[key]for key in ['componentId','provider','environment','name']}})
        if item['sensitive']is not False or type(item['value'])is not str or not 1<=len(item['value'].encode())<=2000:raise ValueError('Sensitive or unbounded values cannot enter application profiles')
        if re.search(r'-----BEGIN .*PRIVATE KEY-----|AKIA[0-9A-Z]{16}|ghp_[A-Za-z0-9]{36}|sk-(?:ant-)?[A-Za-z0-9_-]{20,}',item['value']):raise ValueError('Credential-like output refused')
        if type(item['sourceSha256'])is not str or not re.fullmatch(r'[0-9a-f]{64}',item['sourceSha256']):raise ValueError('Retain the source artifact identity')
        owner=tuple(item[key]for key in ['componentId','provider','environment']);key=owner+(item['name'],)
        if key in by_key:raise ValueError('Duplicate output identity; no version was chosen')
        if owner in snapshots and snapshots[owner]!=item['sourceSha256']:raise ValueError('One component cannot mix output snapshots')
        snapshots[owner]=item['sourceSha256'];by_key[key]=item
    data=template.data;data['format']='approval-application-v1';used={}
    for ref in template.references:
        key=tuple(ref[k]for k in ['componentId','provider','environment','name']);item=by_key.get(key)
        if item is None:raise ValueError('A required native output is unresolved; no default was substituted')
        keys=ref['path'].split('/');target=data
        for part in keys[:-1]:target=target[part]
        target[keys[-1]]=item['value'];used[key]=item
    profile=ApplicationProfile(data)
    receipt={'format':'atmem.application-binding','version':1,'templateSha256':template.sha256,'profileSha256':profile.sha256,'inputs':{'version':1,'outputs':[used[key]for key in sorted(used)]},'status':'structurally_resolved','cloudVerified':False}
    return profile,receipt


def read_json(path):
    with Path(path).open('rb')as stream:raw=stream.read(64001)
    if len(raw)>64000:raise ValueError('Binding artifact exceeds its byte boundary')
    def unique(pairs):
        result={}
        for key,value in pairs:
            if key in result:raise ValueError('Duplicate binding artifact field')
            result[key]=value
        return result
    return json.loads(raw.decode(),object_pairs_hook=unique)


def load_bound_profile(template_path,directory):
    template=ApplicationTemplate(read_json(template_path));directory=Path(directory)
    receipt=read_json(directory/'binding-receipt.json')
    if type(receipt)is not dict or set(receipt)!={'format','version','templateSha256','profileSha256','inputs','status','cloudVerified'}:raise ValueError('Missing or invalid binding receipt; resolve public outputs before starting')
    profile,expected=resolve_template(template,receipt['inputs'])
    if encoded(receipt)!=encoded(expected) or ApplicationProfile(read_json(directory/'application-profile.json')).data!=profile.data:raise ValueError('Binding/profile bytes differ from the owned template and inputs')
    return profile


def write_binding(template_path,ledger_path,directory):
    profile,receipt=resolve_template(ApplicationTemplate(read_json(template_path)),read_json(ledger_path))
    profile_bytes,receipt_bytes=encoded(profile.data),encoded(receipt)
    directory=Path(directory);directory.mkdir(mode=0o700,parents=False,exist_ok=False)
    # Receipt is the commit marker. Readers reject an interrupted/partial bundle.
    with(directory/'application-profile.json').open('xb')as stream:stream.write(profile_bytes)
    with(directory/'binding-receipt.json').open('xb')as stream:stream.write(receipt_bytes)
    return receipt

workflow_profile.py.content:
"""Pure versioned application declaration, shared by engine and delivered runtime."""
import base64
from dataclasses import dataclass
import hashlib
import json
from pathlib import Path
import uuid
from urllib.parse import urlsplit
if __package__:
    from .workflow_payload import PayloadContract,encoded
    from .workflow_contract import bind_payload_contract,bind_application_contract
else:
    from workflow_payload import PayloadContract,encoded
    from workflow_contract import bind_payload_contract,bind_application_contract


def identifier(value):
    if type(value)is not str or str(uuid.UUID(value))!=value:raise ValueError('Use a canonical account UUID')
    return value


def owned_origin(value):
    try:
        parts = urlsplit(value)
        port = parts.port
    except (TypeError, ValueError): raise ValueError('Use the exact owned application origin') from None
    if (type(value) is not str or not parts.hostname or parts.username or parts.password or
        parts.query or parts.fragment or parts.path or
        (port is not None and not 1 <= port <= 65535) or
        any(ord(c) < 33 or ord(c) > 126 for c in value) or
        (parts.scheme != 'https' and not (parts.scheme == 'http' and parts.hostname in {'localhost','127.0.0.1','::1'}))):
        raise ValueError('Use the exact HTTPS origin or explicit loopback test origin')
    return value


IDENTITY_KEYS={
 'aws':('REGION','POOL_ID','CLIENT_ID','AUTH_ORIGIN','AUTH_SCOPE'),
 'azure':('TENANT_ID','API_CLIENT_ID','SPA_CLIENT_ID'),
 'gcp':('PROJECT_NUMBER','REGION','SERVICE_NAME'),
 'ibm':('APPID_TENANT_ID','APPID_CLIENT_ID','APPID_ISSUER','AUTH_SCOPE')}


@dataclass(frozen=True,init=False)
class ApplicationProfile:
    _encoded:bytes

    def __init__(self,value):
        raw=encoded(value);data=json.loads(raw)
        keys={'format','provider','componentId','environment','accountId','publicOrigin','operationKind','identitySettings','payloadContract','destinationContract'}
        if type(data)is not dict or set(data)!=keys or data['format']!='approval-application-v1':raise ValueError('Use the exact versioned application profile')
        if type(data['provider'])is not str or data['provider']not in IDENTITY_KEYS:raise ValueError('Use the selected application provider')
        if type(data['componentId'])is not str or not 1<=len(data['componentId'].encode('utf-8'))<=512 or any(ord(c)<32 for c in data['componentId']):raise ValueError('Use the complete bounded component identity')
        if type(data['environment'])is not str or data['environment']not in {'staging','production','qualification'}:raise ValueError('Use the reviewed deployment environment')
        identifier(data['accountId']);owned_origin(data['publicOrigin'])
        if type(data['operationKind'])is not str or data['operationKind']not in {'document','draft','account_change'}:raise ValueError('Use an explicit owned operation policy')
        identity=data['identitySettings']
        if type(identity)is not dict or set(identity)!=set(IDENTITY_KEYS[data['provider']])or any(type(v)is not str or not 1<=len(v.encode('utf-8'))<=2000 for v in identity.values()):raise ValueError('Use the complete nonsecret native identity settings')
        if type(data['destinationContract'])is not dict or 'applicationContractSha256'in data['destinationContract']:raise ValueError('Use the reviewed base destination; application binding is generated')
        bind_payload_contract(data['destinationContract'],PayloadContract(data['payloadContract']))
        object.__setattr__(self,'_encoded',raw)

    @property
    def data(self):return json.loads(self._encoded)
    @property
    def payload(self):return PayloadContract(self.data['payloadContract'])
    @property
    def sha256(self):return hashlib.sha256(self._encoded).hexdigest()
    @property
    def destination(self):return bind_application_contract(bind_payload_contract(self.data['destinationContract'],self.payload),self.sha256)
    @property
    def binding_sha256(self):
        value={key:self.data[key]for key in ['provider','componentId','environment','accountId']}
        return hashlib.sha256(encoded(value)).hexdigest()
    @property
    def namespace(self):
        # Explicit native alias, not truncation of the saved component identity.
        # 88-bit digest encoding fits the existing task/notification constraints.
        return 'w'+base64.b32encode(bytes.fromhex(self.binding_sha256)[:11]).decode().lower().rstrip('=')


def load_profile(path):
    if not isinstance(path,(str,Path))or not Path(path).is_absolute():raise ValueError('Use an owned absolute application profile path')
    with Path(path).open('rb')as stream:raw=stream.read(64001)
    if len(raw)>64000:raise ValueError('Application profile exceeds its byte boundary')
    def unique(pairs):
        result={}
        for key,value in pairs:
            if key in result:raise ValueError('Duplicate application profile field')
            result[key]=value
        return result
    return ApplicationProfile(json.loads(raw.decode('utf-8'),object_pairs_hook=unique))

workflow_application.py.content:
"""Owned application assembly; imports neither API/JWT nor cloud SDK at startup.

Profiles are nonsecret reviewed artifacts. They do not select Python modules,
credential paths, migrations or deployment actions. Domain stages remain trusted
source supplied by the bootstrap, never executable strings from client data.
"""
import hashlib
from workflow_payload import encoded
from workflow_configuration import native_database,native_identity_realm
from workflow_profile import ApplicationProfile,load_profile,IDENTITY_KEYS

def checked_environment(profile,environment):
    if type(profile)is not ApplicationProfile:raise ValueError('Use an immutable owned application profile')
    copied=dict(environment);data=profile.data
    for key,expected in [('PROVIDER',data['provider']),('ACCOUNT_ID',data['accountId']),('ENVIRONMENT',data['environment']),('WORKFLOW_NAMESPACE',profile.namespace),('PUBLIC_ORIGIN',data['publicOrigin'])]:
        if key in copied and copied[key]!=expected:raise ValueError('Runtime configuration differs from the owned application profile')
    for key,expected in data['identitySettings'].items():
        if key in copied and copied[key]!=expected:raise ValueError('Native identity differs from the owned application profile')
    return copied


def membership_key(profile,subject):
    """Derived enrollment key from the complete verified subject and native realm.

    This is not an authentication function. Enrollment is an operator action;
    the API calls it only after cryptographic native verification. No subject
    characters are clipped; the native IdP remains the authoritative identity.
    """
    if type(profile)is not ApplicationProfile or type(subject)is not str or not 1<=len(subject.encode('utf-8'))<=16384 or any(ord(c)<32 for c in subject):raise ValueError('Use the complete verified native subject')
    data=profile.data
    return 'native-'+hashlib.sha256(encoded({'provider':data['provider'],'issuer':native_identity_realm(data['provider'],data['identitySettings']),'subject':subject})).hexdigest()


def create_native_api(profile,environment,*,connection=None,jwks=None,review_policy=None):
    from workflow_identity import native_staff_identity
    from workflow_worker import producer_store
    from workflow_http import create_app
    env=checked_environment(profile,environment);data=profile.data;provider=data['provider']
    identity=native_staff_identity(provider,data['identitySettings'],jwks=jwks)
    dsn=connection if connection is not None else native_database(provider,env,'api')
    store=producer_store(dsn,destination_contract=profile.destination,namespace=profile.namespace,payload_contract=profile.payload,operation_kind=data['operationKind'],review_policy=review_policy)
    def verify(token):return membership_key(profile,identity.verify(token))
    return create_app(verify,store,account_id=data['accountId'],public_origin=data['publicOrigin'],operation_kind=data['operationKind'],token_header=identity.token_header)


class _OwnedStage:
    def __init__(self,stage,account,kind):self.stage=stage;self.account=account;self.kind=kind
    def __getattr__(self,name):return getattr(self.stage,name)
    def __call__(self,row,*args,**kwargs):
        from workflow_errors import InvalidDispatch
        if str(row.get('account_id'))!=self.account:raise InvalidDispatch('Work belongs to a different application account; no stage was invoked')
        if row.get('kind')!=self.kind:raise InvalidDispatch('Work has a different operation policy; no stage was invoked')
        return self.stage(row,*args,**kwargs)


def create_native_worker(profile,environment,processor,deliver,*,connection=None,idempotent_destination=False,review_policy=None):
    from workflow_worker import WorkflowRuntime
    env=checked_environment(profile,environment);data=profile.data
    if not callable(processor)or not callable(deliver):raise ValueError('Supply trusted application stages')
    dsn=connection if connection is not None else native_database(data['provider'],env,'worker')
    return WorkflowRuntime(dsn,_OwnedStage(processor,data['accountId'],data['operationKind']),_OwnedStage(deliver,data['accountId'],data['operationKind']),
        destination_contract=profile.destination,payload_contract=profile.payload,operation_kind=data['operationKind'],namespace=profile.namespace,idempotent_destination=idempotent_destination,review_policy=review_policy)

workflow_configuration.py.content:
"""Provider-native database configuration and reviewed public origins.

No cloud request, secret read, HTTP or JWT adapter is loaded at import.
"""
from pathlib import Path
from workflow_profile import owned_origin
from workflow_connection import aws_database,azure_database,gcp_database,ibm_database

def mounted_secret(path,*,maximum=500):
    if not isinstance(path,str)or not Path(path).is_absolute()or type(maximum)is not int or not 1<=maximum<=20000:raise ValueError('Use the owned mounted secret file')
    def read():
        with Path(path).open('rb')as stream:raw=stream.read(maximum+1)
        if not raw or len(raw)>maximum or b'\0'in raw:raise ValueError('Mounted secret is unavailable')
        return raw.decode('utf-8')
    return read

def native_database(provider,environment,role):
    if role not in {'api','worker','migration'}:raise ValueError('Use an owned runtime database role')
    env=environment;common={'database':env['DATABASE_NAME'],'role':role}
    if provider=='gcp':
        transport=env.get('DATABASE_TRANSPORT','cloudsql-socket')
        if transport not in {'cloudsql-socket','cloudsql-private-proxy'}:raise ValueError('Use the owned Cloud SQL transport')
        return gcp_database(**common,connection_name=env['DATABASE_CONNECTION_NAME'],service_account_email=env['DATABASE_SERVICE_ACCOUNT'],private_proxy=transport=='cloudsql-private-proxy')
    common.update({'host':env['DATABASE_HOST'],'user':env['DATABASE_USER'],'ca_file':env['DATABASE_CA_FILE']})
    if provider=='aws':return aws_database(**common,region=env['REGION'])
    if provider=='azure':return azure_database(**common,managed_identity_client_id=env['WORKLOAD_IDENTITY_CLIENT_ID'])
    if provider=='ibm':return ibm_database(**common,port=int(env['DATABASE_PORT']),password=mounted_secret(env['DATABASE_PASSWORD_FILE']))
    raise ValueError('Unsupported owned database provider')

def native_identity_realm(provider,settings):
    """Issuer identity from owned settings, never unverified token claims.

    Native verifiers separately enforce client/audience/scope. Changing those
    controls must not rename a person within the same issuer's membership.
    """
    if provider=='aws':return 'https://cognito-idp.'+settings['REGION']+'.amazonaws.com/'+settings['POOL_ID']
    if provider=='azure':return 'https://login.microsoftonline.com/'+settings['TENANT_ID']+'/v2.0'
    if provider=='gcp':return 'https://cloud.google.com/iap'
    if provider=='ibm':return settings['APPID_ISSUER']
    raise ValueError('Unsupported owned identity provider')

workflow_identity.py.content:
"""Native staff login bindings. Database membership remains authoritative for roles.

Configuration is compiler/operator-owned. Never derive a signing-key URL, tenant,
issuer, OAuth audience or processing role from caller claims or document content.
JWT validity is bounded by expiry, not a claim of continuous IdP revocation.
"""
from dataclasses import dataclass
import re
import uuid
import jwt
from durable_workflow import Denied

UUID=r'[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}'

class CognitoStaffVerifier:
    def __init__(self,region,pool_id,client_id,scope,*,jwks=None):
        if(not isinstance(region,str)or not re.fullmatch(r'[a-z]{2}-[a-z]+-[0-9]',region)
           or not isinstance(pool_id,str)or not re.fullmatch(re.escape(region)+r'_[A-Za-z0-9]{1,55}',pool_id)
           or not isinstance(client_id,str)or not re.fullmatch(r'[a-z0-9]{1,128}',client_id)
           or not isinstance(scope,str)or not re.fullmatch(r'[A-Za-z0-9_.-]{1,80}/process',scope)):raise ValueError('Use the exact owned Cognito pool/client/scope')
        self.issuer='https://cognito-idp.'+region+'.amazonaws.com/'+pool_id;self.client_id=client_id;self.scope=scope
        self.jwks=jwks or jwt.PyJWKClient(self.issuer+'/.well-known/jwks.json',timeout=2,lifespan=300)
    def __call__(self,token):
        try:
            if not isinstance(token,str)or not 1<=len(token)<=16384:raise Denied('Verified staff identity required')
            key=self.jwks.get_signing_key_from_jwt(token).key
            # Cognito ACCESS tokens bind the app client in client_id, rather than
            # the ID token's aud. Never accept an ID token as an API credential.
            claims=jwt.decode(token,key,algorithms=['RS256'],issuer=self.issuer,options={'verify_aud':False,'require':['iss','sub','exp','iat','client_id','token_use','scope','username']})
            if(claims['token_use']!='access'or claims['client_id']!=self.client_id
               or not isinstance(claims['scope'],str)or self.scope not in claims['scope'].split()
               or not isinstance(claims['sub'],str)or str(uuid.UUID(claims['sub']))!=claims['sub']
               or not isinstance(claims['username'],str)or not claims['username']
               or any(type(claims[name])is not int for name in ['iat','exp'])or not 0<claims['exp']-claims['iat']<=3600):raise Denied('Verified staff identity required')
            return claims['sub']
        except Exception:raise Denied('Verified staff identity required')from None

@dataclass(frozen=True)
class StaffIdentity:
    verify:object
    public_configuration:dict
    token_header:str|None=None

def native_staff_identity(provider,settings,*,jwks=None):
    if not isinstance(settings,dict)or any(not isinstance(value,str)for value in settings.values()):raise ValueError('Use owned native staff identity settings')
    patterns={
        'aws':{'REGION':r'[a-z]{2}-[a-z]+-[0-9]','POOL_ID':r'[a-z]{2}-[a-z]+-[0-9]_[A-Za-z0-9]{1,55}','CLIENT_ID':r'[a-z0-9]{1,128}','AUTH_ORIGIN':r'https://[a-z0-9][a-z0-9-]{0,61}[a-z0-9]\.auth\.[a-z]{2}-[a-z]+-[0-9]\.amazoncognito\.com','AUTH_SCOPE':r'[A-Za-z0-9_.-]{1,80}/process'},
        'azure':{'TENANT_ID':UUID,'API_CLIENT_ID':UUID,'SPA_CLIENT_ID':UUID},
        'gcp':{'PROJECT_NUMBER':r'[0-9]{6,20}','REGION':r'[a-z]+-[a-z]+[0-9]','SERVICE_NAME':r'[a-z][a-z0-9-]{4,47}[a-z0-9]'},
        'ibm':{'APPID_TENANT_ID':UUID,'APPID_CLIENT_ID':UUID,'APPID_ISSUER':r'https://[a-z]{2}-[a-z]+\.appid\.cloud\.ibm\.com/oauth/v4/'+UUID,'AUTH_SCOPE':r'[A-Za-z0-9_.-]{1,80}/process'}}
    if provider not in patterns or set(settings)!=set(patterns[provider])or any(not re.fullmatch(patterns[provider][name],value)for name,value in settings.items()):raise ValueError('Use exact reviewed native staff identity settings')
    c=dict(settings)
    if provider=='aws':
        if not c['AUTH_ORIGIN'].endswith('.auth.'+c['REGION']+'.amazoncognito.com'):raise ValueError('Cognito authorization region differs from the owned pool')
        verify=CognitoStaffVerifier(c['REGION'],c['POOL_ID'],c['CLIENT_ID'],c['AUTH_SCOPE'],jwks=jwks)
        public={'mode':'oauth-pkce','authOrigin':c['AUTH_ORIGIN'],'authorizationEndpoint':c['AUTH_ORIGIN']+'/oauth2/authorize','tokenEndpoint':c['AUTH_ORIGIN']+'/oauth2/token','clientId':c['CLIENT_ID'],'scopes':'openid '+c['AUTH_SCOPE']}
    elif provider=='azure':
        from azure_structured import EntraVerifier
        verify=EntraVerifier(c,jwks);authority='https://login.microsoftonline.com/'+c['TENANT_ID']+'/oauth2/v2.0'
        public={'mode':'oauth-pkce','authOrigin':'https://login.microsoftonline.com','authorizationEndpoint':authority+'/authorize','tokenEndpoint':authority+'/token','clientId':c['SPA_CLIENT_ID'],'scopes':'openid api://'+c['API_CLIENT_ID']+'/access_as_user'}
    elif provider=='gcp':
        from gcp_structured import IapVerifier
        return StaffIdentity(IapVerifier(c,jwks),{'mode':'proxy','loginPath':'/','logoutPath':None},'x-goog-iap-jwt-assertion')
    else:
        from ibm_structured import AppIdVerifier
        if not c['APPID_ISSUER'].endswith('/oauth/v4/'+c['APPID_TENANT_ID']):raise ValueError('App ID issuer tenant differs from the owned tenant')
        verify=AppIdVerifier(c,jwks);issuer=c['APPID_ISSUER'];origin=issuer.split('/oauth/v4/')[0]
        public={'mode':'oauth-pkce','authOrigin':origin,'authorizationEndpoint':issuer+'/authorization','tokenEndpoint':issuer+'/token','clientId':c['APPID_CLIENT_ID'],'scopes':'openid '+c['AUTH_SCOPE']}
    return StaffIdentity(verify,public)

workflow_http.py.content:
"""Typed approval-workflow HTTP boundary with operator-owned tenant and policy.

No domain inference, identity provider, role administration or automatic execution
is provided here. Trusted bootstrap supplies the verifier, typed store and origin.
Acceptance means durable enqueue, never completed processing or delivery.
"""
import asyncio
import json
import re
import threading
from fastapi import FastAPI, Request
from fastapi.responses import JSONResponse
from starlette.concurrency import run_in_threadpool
from durable_workflow import Principal, Denied, Missing, Conflict, identifier
from workflow_payload import PayloadContract
from workflow_configuration import owned_origin

MAX_BODY = 66000  # Includes the envelope; typed data itself remains <=64000.


class BodyTooLarge(ValueError): pass
class UnsupportedBody(ValueError): pass
class Busy(RuntimeError): pass


def public_operation(row, *, include_source=False):
    result = {'id':str(row['id']), 'state':row['state'], 'revision':row['result_revision'],
            'result':row['result'], 'receipt':row['receipt'],
            'createdAt':row['created_at'].isoformat(), 'updatedAt':row['updated_at'].isoformat()}
    if include_source: result['source'] = row['source_ref']
    return result


async def body(request, fields):
    types = request.headers.getlist('content-type')
    if len(types) != 1 or types[0].split(';')[0].lower() != 'application/json':
        raise UnsupportedBody('Use application/json')
    lengths = request.headers.getlist('content-length')
    if len(lengths) > 1 or lengths and not re.fullmatch(r'0|[1-9][0-9]{0,8}',lengths[0]):
        raise ValueError('Use an exact body length')
    expected = int(lengths[0]) if lengths else None
    if expected is not None and expected > MAX_BODY: raise BodyTooLarge()
    raw = bytearray()
    async with asyncio.timeout(5):
        async for chunk in request.stream():
            if len(raw) + len(chunk) > MAX_BODY: raise BodyTooLarge()
            raw.extend(chunk)
    if expected is not None and len(raw) != expected: raise ValueError('Body length differs')
    def unique(pairs):
        result = {}
        for key, value in pairs:
            if key in result: raise ValueError('Duplicate application field')
            result[key] = value
        return result
    def constant(_): raise ValueError('Nonfinite JSON is unsupported')
    value = json.loads(raw.decode('utf-8'),object_pairs_hook=unique,parse_constant=constant)
    if type(value) is not dict or set(value) != set(fields): raise ValueError('Use the exact operation envelope')
    return value


def create_app(verify, store, *, account_id, public_origin, operation_kind='draft', token_header=None):
    identifier(account_id); origin = owned_origin(public_origin)
    if not callable(verify) or type(getattr(store,'payload_contract',None)) is not PayloadContract:
        raise ValueError('Supply an owned verifier and typed application store')
    if type(operation_kind) is not str or operation_kind not in {'document','draft','account_change'}: raise ValueError('Use an owned operation policy')
    if getattr(store,'operation_kind',None) not in {None,operation_kind}: raise ValueError('HTTP and stored operation policies differ')
    if token_header is not None and (type(token_header) is not str or token_header != 'x-goog-iap-jwt-assertion'): raise ValueError('Unsupported native identity transport')
    app = FastAPI(docs_url=None,redoc_url=None,openapi_url=None)
    policy = getattr(store, 'review_policy', None)
    def representation(row): return public_operation(row, include_source=policy is not None)
    slots = threading.BoundedSemaphore(20)
    def error(code,status): return JSONResponse({'error':{'code':code}},status_code=status)
    async def actor(request):
        if token_header:
            headers = request.headers.getlist(token_header)
            token = headers[0] if len(headers) == 1 else ''
        else:
            headers = request.headers.getlist('authorization')
            supplied = headers[0] if len(headers) == 1 else ''
            token = supplied[7:] if supplied.startswith('Bearer ') else ''
        if not token or len(token) > 16384: raise Denied('Verified identity required')
        try: subject = await run_in_threadpool(verify,token)
        except Exception: raise Denied('Verified identity required') from None
        try: principal = Principal(account_id,subject)
        except ValueError: raise Denied('Verified identity required') from None
        await run_in_threadpool(store.authorize,principal)
        return principal
    async def mutation(request,fields):
        user = await actor(request)
        if request.query_params: raise ValueError('Mutations do not accept query configuration')
        value = await body(request,fields)
        if await actor(request) != user: raise Denied('Identity changed while reading input')
        return user,value
    @app.middleware('http')
    async def boundary(request,next_handler):
        acquired = False
        try:
            origins = request.headers.getlist('origin')
            if len(origins) > 1 or origins and origins[0] != origin: raise Denied('Wrong application origin')
            if request.method not in {'GET','HEAD','OPTIONS'}:
                if origins != [origin]: raise Denied('Exact application origin required')
                acquired = slots.acquire(blocking=False)
                if not acquired: raise Busy()
            response = await next_handler(request)
        except Denied: response = error('access_denied',403)
        except Missing: response = error('not_found',404)
        except Conflict: response = error('conflict',409)
        except BodyTooLarge: response = error('body_too_large',413)
        except UnsupportedBody: response = error('unsupported_content_type',415)
        except Busy: response = error('busy',429)
        except TimeoutError: response = error('body_timeout',408)
        except (ValueError,UnicodeError,RecursionError): response = error('invalid_request',400)
        except Exception: response = error('unavailable',503)
        finally:
            if acquired: slots.release()
        response.headers.update({'Cache-Control':'no-store','X-Content-Type-Options':'nosniff',
            'Referrer-Policy':'no-referrer','Strict-Transport-Security':'max-age=31536000',
            'Content-Security-Policy':"default-src 'none'; frame-ancestors 'none'; base-uri 'none'"})
        return response
    @app.get('/healthz')
    def health(): return {'status':'running'}
    @app.get('/api/session')
    async def session(request:Request):
        user = await actor(request)
        if request.query_params: raise ValueError('No session overrides are accepted')
        return {'roles':await run_in_threadpool(store.authorize,user),'accountMode':'operator-owned'}
    @app.post('/api/operations',status_code=202)
    async def submit(request:Request):
        user,value = await mutation(request,['source'])
        keys = request.headers.getlist('idempotency-key')
        if len(keys) != 1 or not re.fullmatch(r'[A-Za-z0-9][A-Za-z0-9_.:-]{0,199}',keys[0]):
            raise ValueError('Use a stable bounded operation key')
        operation = await run_in_threadpool(store.submit,user,operation_kind,keys[0],value['source'])
        return {'operation':representation(await run_in_threadpool(store.get,user,operation))}
    @app.get('/api/operations')
    async def listing(request:Request):
        user = await actor(request)
        if set(request.query_params)-{'before'} or len(request.query_params.getlist('before')) > 1:
            raise ValueError('Use the bounded operation cursor')
        rows = await run_in_threadpool(store.list,user,before=request.query_params.get('before'),limit=25)
        return {'operations':[representation(row) for row in rows], 'next':str(rows[-1]['id']) if len(rows)==25 else None}
    @app.get('/api/operations/{operation_id}')
    async def detail(operation_id:str,request:Request):
        user = await actor(request)
        if request.query_params: raise ValueError('No operation overrides are accepted')
        return {'operation':representation(await run_in_threadpool(store.get,user,operation_id))}
    @app.post('/api/operations/{operation_id}/review')
    async def review(operation_id:str,request:Request):
        user,value = await mutation(request,['revision','result'])
        if type(value['revision']) is not int: raise ValueError('Use an exact revision')
        row = await run_in_threadpool(store.edit_result,user,operation_id,value['revision'],value['result'])
        return {'operation':representation(row)}
    if policy is not None:
        @app.post('/api/operations/{operation_id}/inspect')
        async def inspect(operation_id:str,request:Request):
            user,_ = await mutation(request,[])
            row = await run_in_threadpool(store.inspect,user,operation_id)
            return {'operation':representation(row),'payloadSha256':store._fingerprint(row),
                    'destination':row['destination_contract']}
        @app.get('/api/operations/{operation_id}/history')
        async def history(operation_id:str,request:Request):
            user = await actor(request)
            if set(request.query_params)-{'afterRevision'}: raise ValueError('Invalid history cursor')
            cursors = request.query_params.getlist('afterRevision')
            if len(cursors)>1 or cursors and not re.fullmatch(r'0|[1-9][0-9]{0,9}',cursors[0]): raise ValueError('Invalid history cursor')
            rows = await run_in_threadpool(store.result_history,user,operation_id,after_revision=int(cursors[0]) if cursors else 0)
            return {'history':[{'revision':r['revision'],'result':r['result'],'actor':r['actor'],
                                'createdAt':r['created_at'].isoformat()} for r in rows]}
    @app.post('/api/operations/{operation_id}/approve')
    async def approve(operation_id:str,request:Request):
        user,value = await mutation(request,['revision','payloadSha256'] if policy is not None else ['revision'])
        if type(value['revision']) is not int: raise ValueError('Use an exact revision')
        if policy is not None:
            row = await run_in_threadpool(store.approve,user,operation_id,value['revision'],value['payloadSha256'])
        else:
            row = await run_in_threadpool(store.approve,user,operation_id,value['revision'])
        return {'operation':representation(row)}
    return app

workflow_payload.py.content:
"""Versioned bounded application data contracts, independent of domain/provider.

This is a small closed contract language, not a JSON Schema implementation.
Operator-selected contracts describe data, never roles, executable validation,
destinations or transitions. Domain semantic checks remain the adapter's duty.
"""
from dataclasses import dataclass
import hashlib
import json
import re


def encoded(value):
    def exact(item, depth=0):
        if depth > 32: raise ValueError('Application JSON exceeds its nesting boundary')
        if type(item) is dict:
            if any(type(k) is not str for k in item): raise ValueError('Application object keys must be strings')
            for child in item.values(): exact(child, depth + 1)
        elif type(item) is list:
            for child in item: exact(child, depth + 1)
        elif type(item) not in {str, int, bool, type(None)}:
            raise ValueError('Use exact application JSON types; decimals require an explicit string contract')
    exact(value)
    try:
        raw = json.dumps(value, sort_keys=True, separators=(',', ':'), ensure_ascii=False, allow_nan=False).encode('utf-8')
    except (TypeError, ValueError, UnicodeError, RecursionError):
        raise ValueError('Invalid bounded application JSON') from None
    if len(raw) > 64000:
        raise ValueError('Application JSON exceeds its byte boundary')
    return raw


def schema(value, depth=0, budget=None):
    if budget is None: budget = [256]
    budget[0] -= 1
    if depth > 8 or budget[0] < 0 or type(value) is not dict:
        raise ValueError('Application contract exceeds its structural boundary')
    kind = value.get('type')
    shapes = {'object': {'type', 'properties', 'required'}, 'array': {'type', 'items', 'maxItems'},
              'string': {'type', 'minBytes', 'maxBytes'}, 'integer': {'type', 'minimum', 'maximum'},
              'boolean': {'type'}, 'enum': {'type', 'values'}}
    if type(kind) is not str or kind not in shapes or set(value) != shapes[kind]:
        raise ValueError('Use the closed application contract language')
    if kind == 'object':
        properties, required = value['properties'], value['required']
        if (type(properties) is not dict or not 1 <= len(properties) <= 32 or
            any(type(k) is not str or not re.fullmatch(r'[A-Za-z][A-Za-z0-9_]{0,79}', k) for k in properties) or
            type(required) is not list or any(type(k) is not str for k in required) or
            len(required) != len(set(required)) or not set(required) <= set(properties)):
            raise ValueError('Use bounded exact object fields')
        for item in properties.values(): schema(item, depth + 1, budget)
    elif kind == 'array':
        if type(value['maxItems']) is not int or not 1 <= value['maxItems'] <= 64:
            raise ValueError('Use a bounded array')
        schema(value['items'], depth + 1, budget)
    elif kind == 'string':
        if any(type(value[k]) is not int for k in ['minBytes', 'maxBytes']) or not 0 <= value['minBytes'] <= value['maxBytes'] <= 64000:
            raise ValueError('Use exact UTF-8 byte limits')
    elif kind == 'integer':
        if any(type(value[k]) is not int for k in ['minimum', 'maximum']) or not -(2**53 - 1) <= value['minimum'] <= value['maximum'] <= 2**53 - 1:
            raise ValueError('Use exact portable integer limits')
    elif kind == 'enum':
        items = value['values']
        if (type(items) is not list or not 1 <= len(items) <= 64 or
            any(type(item) is not str or not 1 <= len(item.encode('utf-8')) <= 256 for item in items) or len(items) != len(set(items))):
            raise ValueError('Use a bounded distinct string enumeration')


def conforms(rule, value):
    kind = rule['type']
    valid = False
    if kind == 'object':
        valid = (type(value) is dict and set(rule['required']) <= set(value) <= set(rule['properties']))
        if valid:
            for key, item in value.items(): conforms(rule['properties'][key], item)
    elif kind == 'array':
        valid = type(value) is list and len(value) <= rule['maxItems']
        if valid:
            for item in value: conforms(rule['items'], item)
    elif kind == 'string':
        valid = type(value) is str and rule['minBytes'] <= len(value.encode('utf-8')) <= rule['maxBytes']
    elif kind == 'integer': valid = type(value) is int and rule['minimum'] <= value <= rule['maximum']
    elif kind == 'boolean': valid = type(value) is bool
    elif kind == 'enum': valid = type(value) is str and value in rule['values']
    if not valid: raise ValueError('Application payload does not match its owned contract')


@dataclass(frozen=True, init=False)
class PayloadContract:
    _encoded: bytes

    def __init__(self, value):
        raw = encoded(value)
        copied = json.loads(raw)
        if (type(copied) is not dict or set(copied) != {'version', 'id', 'source', 'result'} or
            type(copied['version']) is not int or copied['version'] != 1 or
            type(copied['id']) is not str or not re.fullmatch(r'[a-z][a-z0-9-]{0,79}', copied['id'])):
            raise ValueError('Use a versioned owned application payload contract')
        budget = [256]
        for side in ['source', 'result']:
            schema(copied[side], budget=budget)
            if copied[side]['type'] != 'object': raise ValueError('Application boundaries require object payloads')
        object.__setattr__(self, '_encoded', raw)

    @property
    def sha256(self): return hashlib.sha256(self._encoded).hexdigest()

    def fields(self, side):
        if side not in {'source', 'result'}: raise ValueError('Use an application input or result boundary')
        return tuple(json.loads(self._encoded)[side]['properties'])

    def validate(self, side, value):
        if side not in {'source', 'result'}: raise ValueError('Use an application input or result boundary')
        # Round trip before validation: no caller mutation can change the bytes
        # validated for persistence. No clipping, coercion or default insertion.
        copied = json.loads(encoded(value))
        conforms(json.loads(self._encoded)[side], copied)
        return copied

workflow_review.py.content:
"""Explicit review/access/semantic policy supplied by trusted application code.

No domain fields, provider selection, executable loading or user configuration.
Semantic validators may reject data, never normalize it. Their implementation and
declared source dependencies are approval-bound; this is not a Python sandbox or
proof that a trusted validator is pure, bounded, or declares every dependency.
"""
from dataclasses import dataclass
import hashlib
import json
from pathlib import Path, PurePosixPath
import re
import types
if __package__:
    from .workflow_payload import PayloadContract, encoded
else:
    from workflow_payload import PayloadContract, encoded


@dataclass(frozen=True, init=False)
class ReviewPolicy:
    _encoded: bytes
    _sources: tuple
    _validator: object
    _payload: PayloadContract

    def __init__(self, payload, *, id, editable_fields, read_scope='owner',
                 inspection_ttl_seconds=300, validator=None, validation_sources=()):
        if type(payload) is not PayloadContract:
            raise ValueError('Supply the exact owned payload contract')
        if type(id) is not str or not re.fullmatch(r'[a-z][a-z0-9-]{0,79}', id):
            raise ValueError('Use a versioned owned review policy identity')
        fields = payload.fields('result')
        if (type(editable_fields) not in {list, tuple} or
            any(type(field) is not str for field in editable_fields) or
            len(set(editable_fields)) != len(editable_fields) or not set(editable_fields) <= set(fields)):
            raise ValueError('Declare the editable top-level result fields explicitly')
        if type(read_scope) is not str or read_scope not in {'owner', 'account'}:
            raise ValueError('Use an explicit application read scope')
        if inspection_ttl_seconds is not None and (type(inspection_ttl_seconds) is not int or not 1 <= inspection_ttl_seconds <= 3600):
            raise ValueError('Use a bounded inspection lifetime or explicit None')
        if type(validation_sources) not in {list, tuple, dict} or len(validation_sources) > 32:
            raise ValueError('Declare bounded trusted validator source dependencies')
        if validator is not None and (type(validator) is not types.FunctionType or validator.__closure__):
            raise ValueError('Supply a trusted module-level semantic validator, not executable data')
        if (validator is None) != (not validation_sources):
            raise ValueError('A semantic validator requires its explicit source dependencies')
        sources = []
        entries = validation_sources.items() if type(validation_sources) is dict else [(Path(source).name,source) for source in validation_sources]
        labels = set()
        for label, source in entries:
            if (type(label) is not str or len(label)>512 or '\\' in label or
                PurePosixPath(label).is_absolute() or any(not re.fullmatch(r'[A-Za-z_][A-Za-z0-9_.-]{0,127}',part) or part in {'.','..'} for part in label.split('/'))):
                raise ValueError('Use explicit portable relative validator dependency labels')
            if label in labels:raise ValueError('Use explicit relative source labels for duplicate filenames')
            labels.add(label)
            path = Path(source)
            if path.is_symlink() or not path.is_file() or path.stat().st_size > 1048576:
                raise ValueError('Use bounded regular validator source files')
            path = path.resolve()
            sources.append((label, path, hashlib.sha256(path.read_bytes()).hexdigest()))
        if validator is not None and Path(validator.__code__.co_filename).resolve() not in {path for _, path, _ in sources}:
            raise ValueError('The semantic validator implementation must be source-bound')
        mechanism = Path(__file__).resolve()
        mechanism_sha256 = hashlib.sha256(mechanism.read_bytes()).hexdigest()
        definition = {'version': 1, 'id': id, 'payloadContractSha256': payload.sha256,
                      'mechanismSha256': mechanism_sha256,
                      'editableFields': sorted(editable_fields), 'readScope': read_scope,
                      'inspectionTtlSeconds': inspection_ttl_seconds,
                      'validator': None if validator is None else {
                          'entrypoint': validator.__qualname__,
                          'sources': {label: sha for label, _, sha in sorted(sources)}}}
        object.__setattr__(self, '_encoded', encoded(definition))
        object.__setattr__(self, '_sources', tuple((path,sha) for _,path,sha in sources)+((mechanism, mechanism_sha256),))
        object.__setattr__(self, '_validator', validator)
        object.__setattr__(self, '_payload', payload)

    @property
    def data(self): return json.loads(self._encoded)

    @property
    def sha256(self): return hashlib.sha256(self._encoded).hexdigest()

    def ensure_current(self):
        for path, sha in self._sources:
            if path.is_symlink() or not path.is_file() or path.stat().st_size > 1048576 or hashlib.sha256(path.read_bytes()).hexdigest() != sha:
                raise ValueError('Review validator sources changed; qualify a new policy binding')

    def validate_result(self, source, result):
        self.ensure_current()
        original = self._payload.validate('source', source)
        value = self._payload.validate('result', result)
        if self._validator is not None:
            before = (encoded(original), encoded(value))
            returned = self._validator(original, value)
            if returned is not None or (encoded(original), encoded(value)) != before:
                raise ValueError('Semantic validation must only accept or reject, never transform data')
        return value

    def validate_edit(self, source, previous, result):
        value = self.validate_result(source, result)
        previous = self._payload.validate('result', previous)
        editable = set(self.data['editableFields'])
        if encoded({k: v for k, v in previous.items() if k not in editable}) != encoded({k: v for k, v in value.items() if k not in editable}):
            raise ValueError('Only explicitly editable result fields may change')
        return value

workflow_contract.py.content:
"""Nonsecret, immutable integration identity included in every human approval."""
import hashlib
import json
import re
if __package__:
    from .workflow_payload import PayloadContract
else:
    from workflow_payload import PayloadContract

def reviewed_contract(value):
    fields={'id','endpointSha256','scope','mappingVersion'}
    optional={'payloadContractSha256','applicationContractSha256','reviewPolicySha256'}
    if (not isinstance(value,dict)or not fields<=set(value)<=fields|optional
        or not isinstance(value['id'],str)or not re.fullmatch(r'[a-z0-9-]{1,80}',value['id'])
        or not isinstance(value['endpointSha256'],str)or not re.fullmatch(r'[0-9a-f]{64}',value['endpointSha256'])
        or not isinstance(value['scope'],str)or not 1<=len(value['scope'])<=200 or any(ord(c)<33 or ord(c)>126 for c in value['scope'])
        or type(value['mappingVersion'])is not int or not 1<=value['mappingVersion']<=10000
        or any(key in value and(not isinstance(value[key],str)or not re.fullmatch(r'[0-9a-f]{64}',value[key]))for key in optional)):raise ValueError('Supply the reviewed nonsecret destination contract identity')
    return json.loads(json.dumps(value))

def normalized_contract(endpoint,scope):
    return reviewed_contract({'id':'normalized-action-v1','endpointSha256':hashlib.sha256(endpoint.encode('utf-8')).hexdigest(),'scope':scope,'mappingVersion':1})

def bind_payload_contract(destination,payload_contract):
    result=reviewed_contract(destination)
    if payload_contract is not None and type(payload_contract)is not PayloadContract:raise ValueError('Use an owned immutable application payload contract')
    bound=result.get('payloadContractSha256')
    if bound is not None and(payload_contract is None or bound!=payload_contract.sha256):raise ValueError('Application contract does not match its destination binding')
    if payload_contract is not None:result['payloadContractSha256']=payload_contract.sha256
    return result

def bind_application_contract(destination,sha256):
    result=reviewed_contract(destination)
    if type(sha256)is not str or not re.fullmatch(r'[0-9a-f]{64}',sha256):raise ValueError('Use an exact owned application declaration digest')
    if 'applicationContractSha256'in result and result['applicationContractSha256']!=sha256:raise ValueError('Application declaration binding changed')
    result['applicationContractSha256']=sha256
    return result

def bind_review_policy(destination,payload_contract,review_policy):
    if __package__:
        from .workflow_review import ReviewPolicy
    else:
        from workflow_review import ReviewPolicy
    result=bind_payload_contract(destination,payload_contract)
    bound=result.get('reviewPolicySha256')
    if review_policy is None:
        if bound is not None:raise ValueError('The destination requires its exact review policy')
        return result
    if type(review_policy)is not ReviewPolicy or payload_contract is None or review_policy.data['payloadContractSha256']!=payload_contract.sha256:
        raise ValueError('Use an owned review policy matching the exact payload contract')
    review_policy.ensure_current()
    if bound is not None and bound!=review_policy.sha256:raise ValueError('Review policy differs from its destination binding')
    result['reviewPolicySha256']=review_policy.sha256
    return result

workflow_connection.py.content:
"""Provider-native fresh PostgreSQL credentials with explicit transport identity.

No connection or cloud request occurs at import. Constructors accept deployment
configuration, not browser/model input. Managed Cloud SQL Unix transport relies on
the separately configured native connector for upstream TLS; it is never a plain
TCP fallback. IBM database passwords are distinct from IBM control-plane IAM.
"""
from pathlib import Path
import re
import time
import threading
import uuid
from psycopg.conninfo import make_conninfo
from workflow_errors import TemporaryWork

class DatabaseCredentialUnavailable(TemporaryWork):pass

class DatabaseConnection:
    def __init__(self,provider,host,port,database,user,credential,*,ca_file=None,managed_cloudsql=False,managed_proxy_tcp=False,role='worker'):
        if provider not in {'aws','azure','gcp','ibm'}or role not in {'api','worker','migration'}or type(managed_cloudsql)is not bool or type(managed_proxy_tcp)is not bool or(managed_cloudsql and managed_proxy_tcp):raise ValueError('Invalid owned database identity')
        if not isinstance(database,str)or not re.fullmatch(r'[a-zA-Z][a-zA-Z0-9_]{0,62}',database)or not isinstance(user,str)or not 1<=len(user.encode('utf-8'))<=63 or any(ord(c)<33 or ord(c)>126 for c in user):raise ValueError('Use exact native database and role names')
        if type(port)is not int or not 1<=port<=65535 or not callable(credential):raise ValueError('Invalid owned database credential source')
        if managed_proxy_tcp:
            # An explicit compiler-owned same-instance proxy, never a fallback
            # after native TLS failure. The pinned proxy enforces upstream TLS
            # and private-IP connectivity. No configurable TCP host/port here.
            if provider!='gcp'or host!='127.0.0.1'or port!=5432 or ca_file is not None:raise ValueError('Use the exact owned Cloud SQL loopback proxy')
            transport={'sslmode':'disable'}
        elif managed_cloudsql:
            if provider!='gcp'or not isinstance(host,str)or not re.fullmatch(r'/cloudsql/[a-z][a-z0-9-]{4,28}[a-z0-9]:[a-z]+-[a-z]+[1-9][0-9]?:[a-z][a-z0-9-]{0,62}',host)or len((host+'/.s.PGSQL.'+str(port)).encode())>103 or ca_file is not None:raise ValueError('Use the owned Cloud SQL managed Unix socket with upstream connector TLS')
            transport={'sslmode':'disable'}
        else:
            if not isinstance(host,str)or not re.fullmatch(r'[a-z0-9](?:[a-z0-9.-]{0,251}[a-z0-9])?',host)or'..'in host:raise ValueError('Use an exact owned native database hostname')
            if not isinstance(ca_file,(str,Path))or not Path(ca_file).is_absolute()or not Path(ca_file).is_file():raise ValueError('Supply the reviewed native CA certificate file')
            if b'-----BEGIN CERTIFICATE-----'not in Path(ca_file).read_bytes():raise ValueError('Native database CA must contain PEM certificates')
            transport={'sslmode':'verify-full','sslrootcert':str(ca_file),'ssl_min_protocol_version':'TLSv1.2'}
        self.provider=provider;self.credential=credential
        self.parameters={'host':host,'port':port,'dbname':database,'user':user,'application_name':'atmem-workflow-'+role,'connect_timeout':5,'gssencmode':'disable','passfile':'/dev/null',**transport}
    def __repr__(self):return'<Reviewed '+self.provider+' database credential factory>'
    def __call__(self):
        try:
            password=self.credential()
            if not isinstance(password,str)or not password or '\0'in password or len(password.encode('utf-8'))>20000:raise ValueError('Invalid credential')
            return make_conninfo(**self.parameters,password=password)
        except Exception:raise DatabaseCredentialUnavailable('Database credential is temporarily unavailable')from None

def aws_database(*,host,region,database,user,ca_file,role='worker',client=None):
    if not isinstance(region,str)or not re.fullmatch(r'[a-z]{2}-[a-z]+-[0-9]',region)or not isinstance(host,str)or not host.endswith('.'+region+'.rds.amazonaws.com'):raise ValueError('Use the actual regional RDS endpoint, not a custom DNS alias')
    cached={'client':client};client_lock=threading.Lock()
    def password():
        if cached['client']is None:
            with client_lock:
                if cached['client']is None:
                    import boto3
                    from botocore.config import Config
                    cached['client']=boto3.Session().client('rds',region_name=region,config=Config(proxies={},connect_timeout=1,read_timeout=2,retries={'total_max_attempts':1}))
        return cached['client'].generate_db_auth_token(DBHostname=host,Port=5432,DBUsername=user,Region=region)
    return DatabaseConnection('aws',host,5432,database,user,password,ca_file=ca_file,role=role)

def azure_database(*,host,database,user,ca_file,managed_identity_client_id,role='worker',credential=None):
    if not isinstance(host,str)or not re.fullmatch(r'[a-z0-9][a-z0-9-]{1,61}[a-z0-9]\.postgres\.database\.azure\.com',host):raise ValueError('Use the actual Azure PostgreSQL endpoint')
    if not isinstance(managed_identity_client_id,str)or str(uuid.UUID(managed_identity_client_id))!=managed_identity_client_id:raise ValueError('Use the dedicated database workload identity client ID')
    cached={'credential':credential}
    def password():
        if cached['credential']is None:
            from azure.identity import ManagedIdentityCredential
            cached['credential']=ManagedIdentityCredential(client_id=managed_identity_client_id,retry_total=0,connection_timeout=1,read_timeout=2)
        access=cached['credential'].get_token('https://ossrdbms-aad.database.windows.net/.default')
        if type(access.expires_on)is not int or access.expires_on<time.time()+30:raise ValueError('Database token is expiring')
        return access.token
    return DatabaseConnection('azure',host,5432,database,user,password,ca_file=ca_file,role=role)

def google_metadata_token(session=None):
    import requests
    import json
    session=session or requests.Session();session.trust_env=False;deadline=time.monotonic()+4
    try:
        with session.get('http://metadata.google.internal/computeMetadata/v1/instance/service-accounts/default/token',headers={'Metadata-Flavor':'Google'},timeout=(1,2),allow_redirects=False,stream=True)as response:
            if response.status_code!=200 or response.headers.get('Metadata-Flavor')!='Google':raise ValueError('Unverified workload identity')
            raw=bytearray()
            for chunk in response.iter_content(1):
                raw.extend(chunk)
                if len(raw)>8192 or time.monotonic()>deadline:raise ValueError('Workload identity response boundary')
        def unique(pairs):
            value={}
            for key,item in pairs:
                if key in value:raise ValueError('Duplicate credential field')
                value[key]=item
            return value
        value=json.loads(raw,object_pairs_hook=unique)
        if not isinstance(value,dict)or value.get('token_type')!='Bearer'or type(value.get('expires_in'))is not int or value['expires_in']<60 or not isinstance(value.get('access_token'),str)or not value['access_token']:raise ValueError('Unverified workload token')
        return value['access_token']
    except Exception:raise DatabaseCredentialUnavailable('Database workload identity is temporarily unavailable')from None

def gcp_database(*,connection_name,service_account_email,database,role='worker',credential=None,private_proxy=False):
    if not isinstance(connection_name,str)or not re.fullmatch(r'[a-z][a-z0-9-]{4,28}[a-z0-9]:[a-z]+-[a-z]+[1-9][0-9]?:[a-z][a-z0-9-]{0,62}',connection_name)or type(private_proxy)is not bool:raise ValueError('Use the owned Cloud SQL connection name and explicit transport')
    if not isinstance(service_account_email,str)or not re.fullmatch(r'[a-z][a-z0-9-]{4,29}@[a-z][a-z0-9-]{4,28}[a-z0-9]\.iam\.gserviceaccount\.com',service_account_email):raise ValueError('Use the owned service account IAM database identity')
    user=service_account_email.removesuffix('.gserviceaccount.com')
    return DatabaseConnection('gcp','127.0.0.1'if private_proxy else'/cloudsql/'+connection_name,5432,database,user,credential or google_metadata_token,managed_cloudsql=not private_proxy,managed_proxy_tcp=private_proxy,role=role)

def ibm_database(*,host,port,database,user,ca_file,password,role='worker'):
    if not isinstance(host,str)or not host.endswith('.databases.appdomain.cloud'):raise ValueError('Use the native IBM database endpoint and its instance CA')
    # The callable retrieves the dedicated nonadministrative SQL role password
    # from its separately authorized secret store. An IAM token is not substituted.
    return DatabaseConnection('ibm',host,port,database,user,password,ca_file=ca_file,role=role)

workflow_role_bootstrap.py.content:
"""Operator-only native SQL identity bootstrap; never an application endpoint.

Create owned logins, preserve unrelated existing roles, and never implicitly rotate
an existing password. Google IAM users must first be created by this package's
native Cloud SQL user resource. Azure mappings use authoritative object/tenant IDs,
not display-name guesses. Execute only during an authorized destination bootstrap.
"""
import json
import re
import uuid
from psycopg import sql
from psycopg.rows import tuple_row

def canonical_uuid(value):
    if not isinstance(value,str)or str(uuid.UUID(value))!=value:raise ValueError('Use a canonical owned UUID')
    return value

def role_marker(provider,deployment_id,purpose,binding):
    return'atmem-owned-runtime-v1:'+json.dumps({'provider':provider,'deployment':deployment_id,'purpose':purpose,'principal':binding['principal']},sort_keys=True,separators=(',',':'))

def azure_principal(conn,name):
    # Named output aliases avoid relying on case folding of Microsoft's documented
    # camel-case output labels, while preserving its exact six-column contract.
    with conn.cursor(row_factory=tuple_row)as cursor:
        return cursor.execute('SELECT role_name::text,principal_type,object_id,tenant_id,mfa,admin FROM pg_catalog.pgaadauth_list_principals(false) AS mapped(role_name,principal_type,object_id,tenant_id,mfa,admin) WHERE role_name=%s',(name,)).fetchone()

def validate_runtime_bindings(*,provider,deployment_id,bindings,tenant_id=None):
    canonical_uuid(deployment_id)
    if provider not in {'aws','azure','gcp','ibm'}or not isinstance(bindings,dict)or set(bindings)!={'api','worker'}:raise ValueError('Use the complete owned native role bindings')
    if provider=='azure':
        canonical_uuid(tenant_id)
    names=[]
    for purpose,binding in bindings.items():
        fields={'name','principal','created_by_package'}if provider=='gcp'else{'name','principal'}
        if not isinstance(binding,dict)or set(binding)!=fields or not isinstance(binding['name'],str)or not re.fullmatch(r'[A-Za-z0-9_.@-]{1,63}',binding['name']):raise ValueError('Invalid native SQL role binding')
        principal=binding['principal']
        if provider in {'azure','ibm'}:canonical_uuid(principal)
        elif provider=='aws':
            if not isinstance(principal,str)or not re.fullmatch(r'arn:aws:iam::[0-9]{12}:role/[A-Za-z0-9+=,.@_/-]{1,512}',principal):raise ValueError('Use the exact owned workload role ARN')
        else:
            if(binding['created_by_package']is not True or not isinstance(principal,str)or not re.fullmatch(r'[a-z][a-z0-9-]{4,29}@[a-z][a-z0-9-]{4,28}[a-z0-9]\.iam\.gserviceaccount\.com',principal)or binding['name']!=principal.removesuffix('.gserviceaccount.com')):raise ValueError('Only the package-created service account IAM user may be admitted here')
        names.append(binding['name'])
    if len(set(names))!=2:raise ValueError('API and worker logins must be separate')
    return bindings

def bootstrap_runtime_roles(conn,*,provider,deployment_id,bindings,passwords=None,tenant_id=None):
    validate_runtime_bindings(provider=provider,deployment_id=deployment_id,bindings=bindings,tenant_id=tenant_id)
    if provider=='azure'and conn.info.dbname!='postgres':raise ValueError('Azure principal mapping must run on the native postgres database before application schema bootstrap')
    if provider=='ibm'and not callable(passwords):raise ValueError('Use the separate owned secret-store password reader')
    # Serialize bootstrap for one deployment, including retries after a partial
    # operator run. This lock does not confer ownership over an unrelated role.
    conn.execute('SELECT pg_advisory_xact_lock(hashtextextended(%s,0))',('atmem-native-role-bootstrap:'+deployment_id,))
    result={}
    for purpose,binding in bindings.items():
        name=binding['name'];identifier=sql.Identifier(name);marker=role_marker(provider,deployment_id,purpose,binding)
        with conn.cursor(row_factory=tuple_row)as cursor:
            existing=cursor.execute("SELECT r.oid,shobj_description(r.oid,'pg_authid'),r.rolsuper,r.rolcreatedb,r.rolcreaterole,r.rolreplication,r.rolbypassrls,r.rolcanlogin FROM pg_roles r WHERE rolname=%s",(name,)).fetchone()
        if existing:
            if any(existing[2:7])or not existing[7]:raise ValueError('Native runtime role must be a nonadministrative login')
            if existing[1]!=marker:
                if provider!='gcp'or existing[1]is not None:raise ValueError('Refusing to adopt or repoint an unrelated existing database role')
                with conn.cursor(row_factory=tuple_row)as cursor:
                    parents=cursor.execute('SELECT p.rolname FROM pg_auth_members m JOIN pg_roles p ON p.oid=m.roleid WHERE m.member=%s',(existing[0],)).fetchall()
                if not parents or not {row[0]for row in parents}<={'cloudsqliamuser','cloudsqliamserviceaccount'}:raise ValueError('The native service-account authentication marker is missing or broadened')
                # Complete ownership/effective-grant admission still runs in the
                # application database before runtime grants are installed.
                conn.execute(sql.SQL('COMMENT ON ROLE {} IS {}').format(identifier,sql.Literal(marker)))
        elif provider=='gcp':raise ValueError('Apply the owned Cloud SQL IAM user resource before SQL bootstrap')
        elif provider=='azure':
            conn.execute("SELECT pg_catalog.pgaadauth_create_principal_with_oid(%s,%s,'service',false,false)",(name,binding['principal']))
            conn.execute(sql.SQL('COMMENT ON ROLE {} IS {}').format(identifier,sql.Literal(marker)))
        else:
            password=sql.SQL('NULL')
            if provider=='ibm':
                secret=passwords(purpose,binding['principal'])
                if not isinstance(secret,str)or not 24<=len(secret.encode('utf-8'))<=500 or '\0'in secret:raise ValueError('Use a strong operator-managed SQL credential')
                # Send a client-side SCRAM verifier rather than plaintext in SQL
                # DDL/statement logs. The verifier remains sensitive DBA metadata.
                verifier=conn.pgconn.encrypt_password(secret.encode(),name.encode(),algorithm=b'scram-sha-256').decode('ascii');password=sql.Literal(verifier)
            conn.execute(sql.SQL('CREATE ROLE {} LOGIN NOSUPERUSER NOCREATEDB NOCREATEROLE NOREPLICATION NOBYPASSRLS PASSWORD {}').format(identifier,password))
            if provider=='aws':
                with conn.cursor(row_factory=tuple_row)as cursor:available=cursor.execute("SELECT 1 FROM pg_roles WHERE rolname='rds_iam'").fetchone()
                if not available:raise ValueError('The native RDS IAM authentication role is missing')
                conn.execute(sql.SQL('GRANT rds_iam TO {}').format(identifier))
            conn.execute(sql.SQL('COMMENT ON ROLE {} IS {}').format(identifier,sql.Literal(marker)))
        if provider=='azure':
            mapped=azure_principal(conn,name)
            if not mapped or len(mapped)!=6 or mapped[0]!=name or mapped[1]!='service'or mapped[2]!=binding['principal']or mapped[3]!=tenant_id or mapped[4]!=0 or mapped[5]!=0:raise ValueError('Native Entra role mapping differs from the owned service principal/tenant or has administrator/MFA flags')
        # Re-read after native creation as well as on repeat operator runs. A
        # provider function must not silently install an administrative login.
        with conn.cursor(row_factory=tuple_row)as cursor:
            flags=cursor.execute('SELECT rolsuper,rolcreatedb,rolcreaterole,rolreplication,rolbypassrls,rolcanlogin FROM pg_roles WHERE rolname=%s',(name,)).fetchone()
            parents=cursor.execute('SELECT p.rolname FROM pg_auth_members m JOIN pg_roles p ON p.oid=m.roleid JOIN pg_roles child ON child.oid=m.member WHERE child.rolname=%s',(name,)).fetchall()
        if not flags or any(flags[:5])or not flags[5]:raise ValueError('Native runtime role must be a nonadministrative login')
        allowed={'rds_iam'}if provider=='aws'else{'cloudsqliamuser','cloudsqliamserviceaccount'}if provider=='gcp'else set()
        if not {row[0]for row in parents}<=allowed:raise ValueError('Native runtime role has an unreviewed inherited authority')
        if provider=='aws':
            # Repair only the authentication membership of an already owned
            # role. Never adopt unrelated logins or remove another grant.
            conn.execute(sql.SQL('GRANT rds_iam TO {}').format(identifier))
        if provider=='gcp'and not parents:raise ValueError('Native Cloud SQL IAM authentication membership is missing')
        conn.execute(sql.SQL('ALTER ROLE {} CONNECTION LIMIT {}').format(identifier,sql.Literal(48 if purpose=='api'else 24)))
        result[purpose]=name
    return result

workflow_worker.py.content:
"""Owned queue integration; concrete processors/HTTP adapters remain separate.

Task arguments contain an operation UUID only. Callbacks are trusted source wired
by the compiler/bootstrap, never model-provided paths, tools or Python code.
"""
import asyncio
import logging
import time
import procrastinate
import psycopg
from durable_workflow import WorkflowStore,LostLease
from workflow_connection import DatabaseCredentialUnavailable
from workflow_errors import TemporaryWork,PermanentWork,ExternalOutcomeUnknown,DestinationNotAttempted,InvalidDispatch
from workflow_contract import bind_review_policy

def _transient_database_error(error,depth=0):
    # ConnectorException and TaskGroup wrappers retain the native cause. Never
    # retry a mixed group containing a programming/schema/authorization failure.
    if depth>12:return False
    if isinstance(error,BaseExceptionGroup):return bool(error.exceptions)and all(_transient_database_error(child,depth+1)for child in error.exceptions)
    if isinstance(error,DatabaseCredentialUnavailable):return True
    if isinstance(error,psycopg.OperationalError):
        state=error.sqlstate
        return state is None or state.startswith('08')or state in {'57P01','57P02','57P03'}
    if error.__cause__ is not None:return _transient_database_error(error.__cause__,depth+1)
    return False

def _namespace(value):
    if not isinstance(value,str)or not value.isascii()or not value.replace('-','').isalnum()or not 1<=len(value)<=20:raise ValueError('Invalid owned workflow namespace')
    return value

def producer_store(dsn,*,destination_contract,namespace='workflow',lease_seconds=600,payload_contract=None,operation_kind=None,review_policy=None):
    """API-side store: synchronous outbox, no worker/model credentials needed."""
    namespace=_namespace(namespace)
    app=procrastinate.App(connector=procrastinate.SyncPsycopgConnector(conninfo=dsn,kwargs={'connect_timeout':5,'options':'-c search_path=pg_catalog,workflow,pg_temp'}))
    def worker_only(operation_id):raise PermanentWork('Run the dedicated owned worker, not an API-side producer')
    extract=app.task(name=namespace+'.extract',queue=namespace+'-extract')(worker_only)
    dispatch=app.task(name=namespace+'.dispatch',queue=namespace+'-dispatch')(worker_only)
    return WorkflowStore(dsn,extract,dispatch,destination_contract=destination_contract,lease_seconds=lease_seconds,payload_contract=payload_contract,operation_kind=operation_kind,review_policy=review_policy)

class WorkflowRuntime:
    def __init__(self,dsn,processor,deliver,*,destination_contract=None,idempotent_destination=False,namespace='workflow',lease_seconds=600,retry_wait=5,payload_contract=None,operation_kind=None,review_policy=None):
        if type(idempotent_destination)is not bool:raise ValueError('Invalid owned worker configuration')
        namespace=_namespace(namespace)
        if type(retry_wait)is not int or not 0<=retry_wait<=300:raise ValueError('Invalid retry policy')
        for stage in [processor,deliver]:
            if hasattr(stage,'timeout_seconds')and stage.timeout_seconds+5>=lease_seconds:raise ValueError('A stage deadline must leave room to commit inside the domain lease')
        if hasattr(deliver,'idempotency_verified')and deliver.idempotency_verified!=idempotent_destination:raise ValueError('Worker replay policy must match the reviewed destination contract')
        if destination_contract is None:destination_contract=getattr(deliver,'contract',None)
        elif hasattr(deliver,'contract')and deliver.contract!=bind_review_policy(destination_contract,payload_contract,review_policy):raise ValueError('Worker and destination integration identities must match')
        if review_policy is not None and hasattr(deliver,'contract')and deliver.contract!=bind_review_policy(destination_contract,payload_contract,review_policy):raise ValueError('Publisher must use the exact review policy binding')
        self.processor=processor;self.deliver=deliver;self.idempotent_destination=idempotent_destination
        async def refreshed_connection():return await asyncio.to_thread(dsn)
        self.app=procrastinate.App(connector=procrastinate.PsycopgConnector(conninfo=refreshed_connection if callable(dsn)else dsn,min_size=1,max_size=8,max_lifetime=600,kwargs={'connect_timeout':5,'options':'-c search_path=pg_catalog,workflow,pg_temp -c statement_timeout=10000 -c lock_timeout=3000'}))
        retry=procrastinate.RetryStrategy(max_attempts=5,wait=retry_wait,retry_exceptions=[TemporaryWork])
        self.extract=self.app.task(name=namespace+'.extract',queue=namespace+'-extract',retry=retry)(self._extract)
        self.dispatch=self.app.task(name=namespace+'.dispatch',queue=namespace+'-dispatch',retry=retry)(self._dispatch)
        # The domain transaction is a synchronous psycopg connection. Keep its
        # producer connector synchronous even while the async worker pool is open;
        # never accidentally bridge that connection into an async cursor context.
        self.store=producer_store(dsn,destination_contract=destination_contract,namespace=namespace,lease_seconds=lease_seconds,payload_contract=payload_contract,operation_kind=operation_kind,review_policy=review_policy)
    async def _fail(self,row,reason,*,retryable=False,ambiguous=True):
        try:await asyncio.to_thread(self.store.fail,str(row['id']),str(row['lease_token']),reason,retryable=retryable,ambiguous=ambiguous)
        except LostLease:return
    async def _extract(self,operation_id):
        try:row=await asyncio.to_thread(self.store.claim_extract,operation_id)
        except psycopg.OperationalError:raise TemporaryWork('Database connection temporarily unavailable before processing')from None
        if row is None:return
        try:
            result=await asyncio.to_thread(self.processor,row)
            await asyncio.to_thread(self.store.record_result,operation_id,str(row['lease_token']),result)
        except LostLease:return
        except TemporaryWork:
            await self._fail(row,'model_unavailable',retryable=True);raise TemporaryWork('Processing temporarily unavailable')from None
        except BaseException as error:
            if isinstance(error,asyncio.CancelledError):raise
            await self._fail(row,'invalid_result');raise PermanentWork('Processing requires review or recovery')from None
    async def _dispatch(self,operation_id):
        try:row=await asyncio.to_thread(self.store.claim_dispatch,operation_id,verified_idempotent_replay=self.idempotent_destination)
        except psycopg.OperationalError:raise TemporaryWork('Database connection temporarily unavailable before dispatch')from None
        if row is None:return
        try:
            receipt=await asyncio.to_thread(self.deliver,row,idempotency_key=str(row['id']),payload_sha256=row['approved_hash'])
            await asyncio.to_thread(self.store.record_sent,operation_id,str(row['lease_token']),receipt)
        except LostLease:return
        except DestinationNotAttempted:
            await self._fail(row,'destination_unavailable',retryable=True,ambiguous=False);raise TemporaryWork('Destination credential temporarily unavailable; no request was made')from None
        except InvalidDispatch:
            await self._fail(row,'destination_rejected',ambiguous=False);raise PermanentWork('Approved dispatch integrity requires review; no request was made')from None
        except ExternalOutcomeUnknown:
            await self._fail(row,'destination_unavailable',retryable=True,ambiguous=True)
            if self.idempotent_destination:raise TemporaryWork('Destination acknowledgement unavailable; stable replay contract applies')from None
            raise PermanentWork('External outcome requires reconciliation before another attempt')from None
        except BaseException as error:
            if isinstance(error,asyncio.CancelledError):raise
            # An unexpected exception can happen after the external service
            # accepted the request, including while committing its receipt.
            await self._fail(row,'destination_unavailable',ambiguous=True)
            raise PermanentWork('External outcome requires reconciliation')from None
    async def recover_once(self):
        # Native heartbeat-based stale detection, never duration-only retry of an
        # actively heartbeating worker. Domain fencing protects resumed callbacks.
        for owned_task in [self.extract,self.dispatch]:
            stalled=await self.app.job_manager.get_stalled_jobs(task_name=owned_task.name,seconds_since_heartbeat=60)
            for job in stalled:await self.app.job_manager.retry_job(job)
        expired=await asyncio.to_thread(self.store.recover_expired)
        repaired=await asyncio.to_thread(self.store.reconcile_notifications)
        return list(dict.fromkeys([*expired,*repaired]))
    async def run(self,*,concurrency=2,recovery_interval=30,**options):
        if type(concurrency)is not int or not 1<=concurrency<=10 or type(recovery_interval)is not int or not 5<=recovery_interval<=300:raise ValueError('Invalid bounded worker options')
        delay=1
        while True:
            started=time.monotonic()
            try:
                # Close even when the initial pool wait fails: retaining a
                # partially opened pool would bypass fresh credentials on retry.
                try:
                    # Admit the exact owned schema before queue registration,
                    # heartbeat/recovery writes or fetching a notification.
                    def admit():
                        with self.store.connect():pass
                    await asyncio.to_thread(admit)
                    await self.app.open_async()
                    async def recovery():
                        while True:
                            await self.recover_once();await asyncio.sleep(recovery_interval)
                    worker_options={'update_heartbeat_interval':10.0,'stalled_worker_timeout':90.0,**options}
                    async with asyncio.TaskGroup()as group:
                        task=group.create_task(recovery())
                        worker=group.create_task(self.app.run_worker_async(queues=[self.extract.queue,self.dispatch.queue],concurrency=concurrency,**worker_options))
                        try:await worker
                        finally:task.cancel()
                finally:await self.app.close_async()
                return
            except Exception as error:
                if not _transient_database_error(error):raise
                # Domain leases, approval hashes and uncertain-delivery rules
                # remain authoritative. Reopening a queue pool cannot resend an
                # external action or reset an operation's attempts/lease.
                logging.getLogger(__name__).warning('Queue database connection interrupted; reconnecting with fresh workload credentials')
                if time.monotonic()-started>=30:delay=1
                await asyncio.sleep(delay);delay=min(delay*2,30)

durable_workflow.py.content:
"""Transactional state and approval fences for owned application workflows.

The HTTP/identity adapter must construct Principal only after native verification.
Live application membership is checked here; this is not an OIDC implementation.
Workers have a separate internal API. No model text chooses a task, role or state.
No queue lock alone establishes exactly-once external side effects: dispatch must
use a verified upstream idempotency contract and preserve the operation identity.
"""
from dataclasses import dataclass
import hashlib
import json
import uuid
import psycopg
from psycopg.rows import dict_row
from psycopg.types.json import Json,Jsonb
from workflow_contract import bind_review_policy
from workflow_database import require_current_schema

class Denied(PermissionError):pass
class Missing(LookupError):pass
class Conflict(ValueError):pass
class LostLease(Conflict):pass

def identifier(value):
    if not isinstance(value,str):raise ValueError('An exact UUID is required')
    parsed=uuid.UUID(value)
    if str(parsed)!=value:raise ValueError('Use a canonical UUID')
    return value

def canonical(value,limit=64000):
    if not isinstance(value,dict) or any(not isinstance(k,str) for k in value):raise ValueError('A JSON object is required')
    try:raw=json.dumps(value,sort_keys=True,separators=(',',':'),ensure_ascii=False,allow_nan=False).encode('utf-8')
    except (ValueError,TypeError,UnicodeError,RecursionError):raise ValueError('Invalid bounded JSON') from None
    if len(raw)>limit:raise ValueError('JSON exceeds its boundary')
    return raw

def stored_json(value):
    # Canonical UTF8 preserves the validated size. Default ASCII escaping can
    # expand a valid non-BMP payload beyond its SQL history bound.
    return Json(value,dumps=lambda item:canonical(item).decode('utf-8'))

@dataclass(frozen=True)
class Principal:
    account_id:str
    subject:str
    def __post_init__(self):
        identifier(self.account_id)
        if not isinstance(self.subject,str) or not 1<=len(self.subject.encode('utf-8'))<=500 or any(ord(c)<32 for c in self.subject):raise ValueError('Invalid verified subject')

class WorkflowStore:
